<?php declare(strict_types=1); use Core\Http\Router; use Modules\Authentication\Controllers\Api\ApiAuthController; use Modules\Authentication\Controllers\AuthController; return function (Router $router): void { $router->group(['middleware' => 'web'], function (Router $router): void { $router->localized('GET', 'login', [AuthController::class, 'showLogin'], 'login'); $router->post('/login', [AuthController::class, 'login'])->name('login.attempt'); $router->post('/logout', [AuthController::class, 'logout']) ->middleware('auth') ->name('logout'); }); $router->group(['prefix' => 'api/auth', 'middleware' => 'api'], function (Router $router): void { $router->post('/login', [ApiAuthController::class, 'login']) ->name('api.auth.login') ->doc('Authenticate with email + password (session based).', [ 'email' => 'required|email', 'password' => 'required|string', ], [ 'success' => true, 'message' => 'Welcome back.', 'data' => ['user' => ['id' => 1, 'name' => 'Admin', 'email' => 'admin@lufly.test']], ]); $router->post('/logout', [ApiAuthController::class, 'logout']) ->middleware('auth') ->name('api.auth.logout') ->doc('Log out the current session.', [], [ 'success' => true, 'message' => 'Logged out.', 'data' => new stdClass(), ]); $router->get('/me', [ApiAuthController::class, 'me']) ->middleware('auth') ->name('api.auth.me') ->doc('Return the authenticated user profile.', [], [ 'success' => true, 'data' => ['user' => ['id' => 1, 'name' => 'Admin', 'email' => 'admin@lufly.test']], ]); }); }; 